import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:19.5px;line-height:1.25}.box h2{font-size:23px;margin-bottom:4px}.tbl{font-size:17.5px}.note,.warn{font-size:17px}.tbl th,.tbl td{padding:2px 6px}.iq ol{font-size:19px;line-height:1.26}.pill{font-size:16px}.grid{gap:10px}.handle{bottom:-12px}.box{padding:9px 12px}.tagline{font-size:19px;margin-bottom:9px}.code{font-family:Consolas,'DejaVu Sans Mono',monospace;background:#f1f5f9;border:1px dashed #94a3b8;border-radius:6px;padding:5px 7px;margin:4px 0;line-height:1.3;font-size:15.5px}</style>
<div class="title">🌱 HxGN EAM CO2e Tracking <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">Turn utility bills and refrigerant leaks into carbon reporting, right inside EAM. (Infor EAM Carbon Dioxide Equivalence brief, 11.6.1)</div>
<div class="grid">
<div class="box c1"><h2>1. What is CO2e?</h2><ul><li>"Carbon dioxide equivalent": the common unit for global warming potential (GWP)</li><li>CO2 is the reference gas (1 : 1)</li><li>Every other gas gets a ratio to CO2</li><li>Needs <b>Asset Sustainability Edition</b> + its CD key</li></ul></div>
<div class="box c2"><h2>2. Ratios in the brief</h2><table class="tbl"><tr><th>Gas</th><th>vs CO2</th></tr><tr><td>CH4 Methane</td><td>21 : 1</td></tr><tr><td>N2O Nitrous oxide</td><td>310 : 1</td></tr><tr><td>HFC-125</td><td>2,800 : 1</td></tr><tr><td>HFC-23</td><td>11,700 : 1</td></tr><tr><td>SF6</td><td>23,900 : 1</td></tr></table></div>
<div class="box c3"><h2>3. Two scenarios</h2><table class="tbl"><tr><th>Scope</th><th>Example</th></tr><tr><td><b>Scope-2</b></td><td>Purchased electricity from a utility</td></tr><tr><td><b>Scope-1</b></td><td>Fugitive gas: refrigerant leaking from HVAC</td></tr></table><div class="note">Category is set on the Commodity (e.g. Electricity, UOM MWH, Scope-2).</div></div>
<div class="box c4"><h2>4. Basic setup (Scope-2)</h2><ul><li><b>Greenhouse Gases</b> screen: gas + CO2e ratio</li><li><b>Unit of Measure</b>: e.g. lbs.</li><li>Install param <b>CO2EUOM</b> = unit for CO2e</li><li><b>Commodities</b>: Electricity, MWH, Scope-2</li><li>System Codes <b>FLTP</b>: fuel types (Coal, Nuclear)</li></ul></div>
<div class="box c5"><h2>5. Supplier + fuels</h2><ul><li>Supplier <b>Commodity</b> tab: utility supplies Electricity</li><li><b>Fuel Mix</b> tab: capacity per fuel → % mix (Date Effective)</li><li>Commodity <b>Fuels</b> tab: gas emitted per UOM of each fuel</li></ul><div class="code">Coal  1,000 MWH/day ≈ 16.7%<br>Nuclear 5,000 MWH/day ≈ 83.3%</div></div>
<div class="box c6"><h2>6. Equipment flags</h2><ul><li>Facility Details: <b>Utility Bill Level</b> + <b>GAS Tracked</b></li><li>Both must be checked to count in CO2e</li><li><b>Design Consumption</b> tab: load ranges + rates, Default Load Factor (0–100)</li></ul><div class="code">0–29%   0.28 MWH/day<br>30–85%  0.22 MWH/day<br>86–100% 0.35 MWH/day</div></div>
<div class="box c7"><h2>7. Daily operation</h2><ul><li><b>Invoice Voucher</b>: Type Non-PO, Status Unfinished</li><li><b>Utility Bill</b> tab: source equipment, commodity, dates, usage, cost</li><li>Set voucher to <b>Approved</b></li><li>Nightly process <b>GDRV</b> updates CO2e tables</li><li><b>Actual Consumption</b> tab can override the Load Factor</li></ul></div>
<div class="box c8"><h2>8. Scope-1 fugitive gas</h2><ul><li>Part (e.g. refrigerant ABC-125) <b>Greenhouse Gases</b> tab: gas + emission per UOM</li><li>Part marked as Fugitive Gas</li><li>Issue/Return Parts: tick <b>Leak</b> on refill</li><li>The leaked quantity is counted as CO2e</li></ul></div>
<div class="box c1" style="grid-column:1 / span 2"><h2>9. The math + the reports</h2><div class="code">CO2e = gas emitted × CO2e ratio<br>e.g. SF6: 0.002 lb/MWH × 23,900 = 47.8 lb CO2e per MWH</div><table class="tbl"><tr><th>Delivered report</th><th>Answers</th></tr><tr><td>Emission of CO2e by Greenhouse Gases</td><td>Which gas drives our footprint?</td></tr><tr><td>Emission of CO2e by Greenhouse Gas Emission Category</td><td>Scope-1 vs Scope-2 split</td></tr><tr><td>Emission of CO2e by Equipment</td><td>Which asset emits most?</td></tr></table></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">10a. Scope-2 flow</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">Gases + CO2EUOM</span><span class="arr">→</span><span class="pill">Commodity + Fuels</span><span class="arr">→</span><span class="pill">Supplier Fuel Mix</span><span class="arr">→</span><span class="pill">Equipment flags</span><span class="arr">→</span><span class="pill">Utility Bill approved</span><span class="arr">→</span><span class="pill">GDRV → reports</span></div></div>
<div class="box iq"><h2>10b. Consultant tips</h2><ol><li>Check both equipment flags</li><li>Keep Fuel Mix dated</li><li>Train storemen on Leak</li><li>Confirm GDRV runs nightly</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">10c. Key points</h2><ul><li>Bills become emissions</li><li>Leaks become Scope-1</li><li>11 screens/tabs, 3 reports</li></ul></div>
</div></div>'''
build("/workspace/instagram-assets/posts/2026-10-30-linkedin-eam-co2e-tracking",B,1620,"Rahul Kumar")
